import React,{useState} from 'react';import {Outlet,NavLink,useNavigate,useLocation} from 'react-router-dom';import {useAuth} from '../contexts/AuthContext';import {LayoutDashboard,ShoppingCart,Package,Receipt,LogOut,Menu,X,Settings,RotateCcw,Percent,UserCircle,Users,History,BarChart3,Store,ChevronDown,Plus} from 'lucide-react';
function StoreSwitcher(){const {availableStores,storeId,switchStore}=useAuth();const [open,setOpen]=useState(false);const navigate=useNavigate();if(availableStores.length<=1)return null;const current=availableStores.find(s=>s.id===storeId)||availableStores[0];return(<div className="relative"><button onClick={()=>setOpen(!open)} className="flex items-center gap-2 px-3 py-1.5 bg-gray-100 rounded-lg"><Store size={16}/><span className="text-sm truncate max-w-[120px]">{current?.name}</span><ChevronDown size={14}/></button>{open&&(<><div className="fixed inset-0 z-40" onClick={()=>setOpen(false)}/><div className="absolute right-0 mt-2 w-56 bg-white rounded-lg shadow-lg border z-50"><div className="p-2">{availableStores.map(s=>(<button key={s.id} onClick={()=>{switchStore(s.id);setOpen(false);}} className={`w-full text-left px-3 py-2 rounded-lg text-sm hover:bg-gray-100 flex justify-between ${s.id===storeId?'bg-green-50 text-green-700':''}`}><span className="truncate">{s.name}</span>{s.id===storeId&&<span>✓</span>}</button>))}<hr className="my-2"/><button onClick={()=>{navigate('/app/settings');setOpen(false);}} className="w-full text-left px-3 py-2 rounded-lg text-sm text-blue-600 hover:bg-blue-50 flex items-center gap-2"><Plus size={14}/> Add New Store</button></div></div></>)}</div>);}
export default function Layout(){const {staff,signOut}=useAuth();const navigate=useNavigate();const location=useLocation();const [sidebarOpen,setSidebarOpen]=useState(false);const isAdmin=staff?.role==='admin';const isManager=staff?.role==='manager'||isAdmin;const nav=[{name:'Dashboard',href:'/app',icon:LayoutDashboard,show:true},{name:'POS',href:'/app/pos',icon:ShoppingCart,show:true},{name:'Inventory',href:'/app/inventory',icon:Package,show:isManager},{name:'Sales',href:'/app/sales',icon:Receipt,show:isManager},{name:'Reports',href:'/app/reports',icon:BarChart3,show:isManager},{name:'Employees',href:'/app/employees',icon:Users,show:isAdmin},{name:'Returns',href:'/app/returns',icon:RotateCcw,show:isManager},{name:'Return History',href:'/app/return-history',icon:History,show:isManager},{name:'Settings',href:'/app/settings',icon:Settings,show:isAdmin},{name:'Discounts',href:'/app/discounts',icon:Percent,show:isAdmin},{name:'Profile',href:'/app/profile',icon:UserCircle,show:true}].filter(i=>i.show);const current=nav.find(i=>i.href===location.pathname)?.name||'Dashboard';const close=()=>setSidebarOpen(false);return(<div className="h-screen flex bg-gray-50 overflow-hidden"><button onClick={()=>setSidebarOpen(true)} className="lg:hidden fixed top-4 left-4 z-40 p-3 bg-white rounded-lg shadow"><Menu className="w-6 h-6"/></button><div className={`fixed inset-y-0 left-0 z-30 w-64 bg-white shadow-xl transform transition-transform lg:translate-x-0 lg:static lg:flex-shrink-0 ${sidebarOpen?'translate-x-0':'-translate-x-full'}`}><div className="p-5 border-b flex justify-between"><h1 className="text-xl font-bold text-green-700 truncate">{staff?.store?.name||'Bwanali POS'}</h1><button onClick={close} className="lg:hidden"><X className="w-5 h-5"/></button></div><nav className="p-3 space-y-1 overflow-y-auto h-[calc(100vh-5rem)]">{nav.map(i=>(<NavLink key={i.name} to={i.href} onClick={close} className={({isActive})=>`flex items-center px-3 py-3 lg:py-2.5 rounded-lg ${isActive?'bg-green-50 text-green-700':'text-gray-700 hover:bg-gray-100'}`}><i.icon className="w-5 h-5 mr-3"/>{i.name}</NavLink>))}<button onClick={async()=>{await signOut();navigate('/login');}} className="flex items-center w-full px-3 py-3 lg:py-2.5 text-red-600 hover:bg-red-50"><LogOut className="w-5 h-5 mr-3"/>Logout</button></nav></div>{sidebarOpen&&<div className="fixed inset-0 z-20 bg-black/50 lg:hidden" onClick={close}/>}<div className="flex-1 flex flex-col min-w-0 overflow-hidden"><header className="bg-white shadow-sm p-4 flex justify-between items-center"><h2 className="text-lg font-semibold truncate">{current}</h2><div className="flex items-center gap-4"><StoreSwitcher/><span className="text-sm text-gray-600 truncate">{staff?.full_name}</span></div></header><main className="flex-1 overflow-auto"><Outlet/></main></div></div>);}
